// Canonical source: source/ui/LibraryNav.tsx. Local copies are generated by
// scripts/sync-navigation.mjs so each standalone library resolves its own React.
import { useEffect, useId, useLayoutEffect, useRef, useState } from 'react'
import { NavLink, useLocation } from 'react-router-dom'
import './LibraryNav.css'

export interface LibraryNavNode {
  id: string
  label: string
  to: string
  children?: LibraryNavNode[]
}
export interface LibraryNavGroup {
  id: string
  label: string
  items: LibraryNavNode[]
}
export interface LibraryNavProps {
  brand: string
  description: string
  groups: LibraryNavGroup[]
  sourceUrl?: string
}

function containsPath(node: LibraryNavNode, path: string): boolean {
  return node.to === path || Boolean(node.children?.some(child => containsPath(child, path)))
}

export function LibraryNav({ brand, description, groups, sourceUrl }: LibraryNavProps) {
  const { pathname } = useLocation()
  const prefix = useId()
  const navigation = useRef<HTMLElement>(null)
  const [open, setOpen] = useState(true)
  const [expanded, setExpanded] = useState<Record<string, boolean>>({})

  // Navigation reveals the current branch. Manual disclosure choices remain in
  // place until another page is selected; folding a branch never navigates.
  useLayoutEffect(() => {
    const active: Record<string, boolean> = {}
    const visit = (node: LibraryNavNode) => {
      if (node.children?.length && containsPath(node, pathname)) {
        active[`node:${node.id}`] = true
        node.children.forEach(visit)
      }
    }
    groups.forEach(group => {
      if (group.items.some(node => containsPath(node, pathname))) {
        active[`group:${group.id}`] = true
        group.items.forEach(visit)
      }
    })
    setExpanded(previous => Object.keys(active).every(key => previous[key] === true) ? previous : { ...previous, ...active })
  }, [pathname, groups])

  useEffect(() => {
    if (!open) return
    const frame = requestAnimationFrame(() => {
      const nav = navigation.current
      const current = nav?.querySelector<HTMLElement>('a[aria-current="page"]')
      if (!nav || !current || !current.getClientRects().length) return
      const outer = nav.getBoundingClientRect()
      const inner = current.getBoundingClientRect()
      if (inner.bottom > outer.bottom - 12) nav.scrollTop += inner.bottom - outer.bottom + 12
      else if (inner.top < outer.top + 12) nav.scrollTop += inner.top - outer.top - 12
    })
    return () => cancelAnimationFrame(frame)
  }, [pathname, open])

  const toggle = (key: string, current: boolean) => setExpanded(previous => ({ ...previous, [key]: !current }))

  const renderNode = (node: LibraryNavNode, depth = 0) => {
    const hasChildren = Boolean(node.children?.length)
    const active = node.to === pathname
    const ancestor = !active && containsPath(node, pathname)
    const key = `node:${node.id}`
    const shown = expanded[key] ?? containsPath(node, pathname)
    const childrenId = `${prefix}-children-${node.id}`
    return <li key={node.id} className={`nav__node${depth ? ' nav__node--child' : ''}${hasChildren ? ' nav__node--parent' : ''}${ancestor ? ' nav__node--ancestor' : ''}`}>
      <div className={`nav__row${active ? ' nav__row--active' : ''}`}>
        <NavLink to={node.to} end className={({ isActive }) => `nav__item${isActive ? ' nav__item--active' : ''}`}>
          {node.label}
        </NavLink>
        {hasChildren && <button type="button" className="nav__branch-toggle"
          aria-label={`${shown ? 'Collapse' : 'Expand'} ${node.label}`} aria-expanded={shown} aria-controls={childrenId}
          onClick={() => toggle(key, shown)}>
          <span className="nav__chevron" aria-hidden="true" />
        </button>}
      </div>
      {hasChildren && <ul id={childrenId} className="nav__children" hidden={!shown}>
        {node.children!.map(child => renderNode(child, depth + 1))}
      </ul>}
    </li>
  }

  return <nav ref={navigation} className={`nav nav--tree${open ? '' : ' nav--collapsed'}`} aria-label={`${brand} component library`}>
    <button type="button" className="nav__toggle" onClick={() => setOpen(value => !value)}
      aria-label={open ? 'Collapse navigation' : 'Expand navigation'} aria-expanded={open}
      aria-controls="library-navigation" title={open ? 'Collapse navigation' : 'Expand navigation'}>{open ? '‹' : '›'}</button>
    <div id="library-navigation" hidden={!open}>
      <div className="nav__brand"><h1>{brand}</h1><p>{description}</p></div>
      {groups.map(group => {
        const shown = expanded[`group:${group.id}`] ?? true
        const listId = `${prefix}-group-${group.id}`
        return <div className="nav__group" key={group.id}>
          <button type="button" className="nav__group-title nav__section-toggle"
            aria-label={`${shown ? 'Collapse' : 'Expand'} ${group.label}`} aria-expanded={shown} aria-controls={listId}
            onClick={() => toggle(`group:${group.id}`, shown)}>
            <span>{group.label}</span><span className="nav__chevron" aria-hidden="true" />
          </button>
          <ul id={listId} className="nav__list" hidden={!shown}>
            {group.items.length ? group.items.map(node => renderNode(node)) : <li className="nav__item nav__item--empty">No components yet</li>}
          </ul>
        </div>
      })}
      {sourceUrl && <div className="nav__source"><a href={sourceUrl} target="_blank" rel="noreferrer">Open source Figma ↗</a></div>}
    </div>
  </nav>
}
